insert into public.personal_insight_trait_texts (trait, level, relationship_type, section, text) values
  ('social', 'high', 'lover', 'who', 'recharges around people and makes friends in minutes'),
  ('social', 'high', 'lover', 'who_they', 'They also recharge around people and make friends in minutes'),
  ('social', 'high', 'lover', 'strength', '{name} brings energy into your life together: new people, new plans, a full weekend if you want one.'),
  ('social', 'high', 'lover', 'challenge', 'A quiet evening at home can feel like a lost evening to {name}, and they may say yes to plans before checking with you.'),
  ('social', 'high', 'lover', 'tip', 'Give {name} a social outlet without you having to be there every time. Encourage their nights out and they come home happier and more present.'),
  ('social', 'high', 'business_partner', 'who', 'is at their best in front of people: clients, events, pitches'),
  ('social', 'high', 'business_partner', 'who_they', 'They''re also at their best in front of people: clients, events, pitches'),
  ('social', 'high', 'business_partner', 'strength', '{name} opens doors. They network easily and can turn a cold contact into a warm one in a single conversation.'),
  ('social', 'high', 'business_partner', 'challenge', '{name} can over-promise in the moment when a client is excited, and the follow-up work then lands on someone else.'),
  ('social', 'high', 'business_partner', 'tip', 'Put {name} on the calls and meetings where people decide. Agree beforehand on what they can promise, so their energy closes deals you can deliver.'),
  ('social', 'high', 'family', 'who', 'is the one who brings everyone together'),
  ('social', 'high', 'family', 'who_they', 'They''re also the one who brings everyone together'),
  ('social', 'high', 'family', 'strength', '{name} keeps the family connected: they remember the gatherings, start the group chats and make sure nobody drifts away.'),
  ('social', 'high', 'family', 'challenge', '{name} may take it personally when you skip a family event or need some time alone.'),
  ('social', 'high', 'family', 'tip', 'When you can''t come, tell {name} early and suggest another time to see each other. They care more about the connection than the specific event.'),
  ('social', 'medium', 'lover', 'who', 'is as happy at a party as on a quiet night in'),
  ('social', 'medium', 'lover', 'who_they', 'They''re as happy at a party as on a quiet night in'),
  ('social', 'medium', 'lover', 'strength', '{name} adapts easily to your social rhythm, whether you want a crowd or just the two of you.'),
  ('social', 'medium', 'lover', 'challenge', 'Because {name} is fine either way, they may not say when they actually need people, or need a break from them.'),
  ('social', 'medium', 'lover', 'tip', 'Ask {name} directly: "Out or in tonight?" They often don''t push for it, but they usually have a preference.'),
  ('social', 'medium', 'business_partner', 'who', 'can work a room or work alone, depending on what the job needs'),
  ('social', 'medium', 'business_partner', 'who_they', 'They can work a room or work alone, depending on what the job needs'),
  ('social', 'medium', 'business_partner', 'strength', '{name} is comfortable with clients and just as comfortable with a quiet day of focused work.'),
  ('social', 'medium', 'business_partner', 'challenge', '{name} may not volunteer for the visible roles, even when they''d do them well.'),
  ('social', 'medium', 'business_partner', 'tip', 'Ask {name} to take one client-facing task this month. They''re good at it, but they rarely ask for the spotlight.'),
  ('social', 'medium', 'family', 'who', 'enjoys family time but also likes their own space'),
  ('social', 'medium', 'family', 'who_they', 'They enjoy family time but also like their own space'),
  ('social', 'medium', 'family', 'strength', '{name} shows up for the important moments without needing to be at every single one.'),
  ('social', 'medium', 'family', 'challenge', '{name} may go quiet for a while without meaning anything by it, which can look like distance.'),
  ('social', 'medium', 'family', 'tip', 'A short, regular check-in works well with {name}. Something like a weekly call keeps you close without feeling like an obligation.'),
  ('social', 'low', 'lover', 'who', 'recharges in quiet and prefers a few deep conversations to a crowd'),
  ('social', 'low', 'lover', 'who_they', 'They recharge in quiet and prefer a few deep conversations to a crowd'),
  ('social', 'low', 'lover', 'strength', '{name} gives you their full attention. When you talk, they really listen, and they remember what you said.'),
  ('social', 'low', 'lover', 'challenge', 'Big groups and long parties drain {name}, even when they enjoy them, and they may need a quiet day after.'),
  ('social', 'low', 'lover', 'tip', 'Plan time alone together, not just events. If you go to a party, agree on a time to leave so {name} can relax and enjoy it.'),
  ('social', 'low', 'business_partner', 'who', 'does their best work with focus and few interruptions'),
  ('social', 'low', 'business_partner', 'who_they', 'They do their best work with focus and few interruptions'),
  ('social', 'low', 'business_partner', 'strength', '{name} thinks before speaking. When they share an opinion in a meeting, it''s usually well thought out.'),
  ('social', 'low', 'business_partner', 'challenge', '{name} may not speak up in big meetings, so their best ideas can stay unsaid.'),
  ('social', 'low', 'business_partner', 'tip', 'Ask {name} for their view one-on-one or in writing before a big meeting. You''ll get their real thinking, not just a nod.'),
  ('social', 'low', 'family', 'who', 'shows love quietly rather than loudly'),
  ('social', 'low', 'family', 'who_they', 'They show love quietly rather than loudly'),
  ('social', 'low', 'family', 'strength', '{name} is the calm, steady presence at family gatherings, the one who notices who''s left out.'),
  ('social', 'low', 'family', 'challenge', 'Long family days can tire {name} out, and they may leave early or go quiet.'),
  ('social', 'low', 'family', 'tip', 'Don''t read {name}''s quietness as a lack of interest. A one-on-one coffee will mean more to them than a big family dinner.'),
  ('curiosity', 'high', 'lover', 'who', 'always wants to learn, try and explore something new'),
  ('curiosity', 'high', 'lover', 'who_they', 'They also always want to learn, try and explore something new'),
  ('curiosity', 'high', 'lover', 'strength', '{name} keeps your relationship fresh: new places, new ideas, new things to talk about over dinner.'),
  ('curiosity', 'high', 'lover', 'challenge', '{name} gets bored with routine quickly and may push for change when you''d rather keep things as they are.'),
  ('curiosity', 'high', 'lover', 'tip', 'Plan one new experience together each month: a place, a class, a recipe. It feeds {name}''s curiosity and gives you shared stories.'),
  ('curiosity', 'high', 'business_partner', 'who', 'is full of ideas and always looking for a better way'),
  ('curiosity', 'high', 'business_partner', 'who_they', 'They''re also full of ideas and always looking for a better way'),
  ('curiosity', 'high', 'business_partner', 'strength', '{name} spots opportunities others miss and isn''t afraid to question how things have always been done.'),
  ('curiosity', 'high', 'business_partner', 'challenge', '{name} may start new ideas before the current ones are finished.'),
  ('curiosity', 'high', 'business_partner', 'tip', 'Keep a shared "later" list for {name}''s new ideas. They feel heard, and the current project stays on track.'),
  ('curiosity', 'high', 'family', 'who', 'loves new ideas, places and conversations'),
  ('curiosity', 'high', 'family', 'who_they', 'They also love new ideas, places and conversations'),
  ('curiosity', 'high', 'family', 'strength', '{name} is the one who suggests the trip, the new restaurant or the topic that gets the whole table talking.'),
  ('curiosity', 'high', 'family', 'challenge', '{name} may find family traditions a bit repetitive and want to change them.'),
  ('curiosity', 'high', 'family', 'tip', 'Let {name} plan part of the next family get-together. They''ll bring something new, and they''ll feel their ideas count.'),
  ('curiosity', 'medium', 'lover', 'who', 'enjoys new things but also values what already works'),
  ('curiosity', 'medium', 'lover', 'who_they', 'They enjoy new things but also value what already works'),
