  ('curiosity', 'low', 'business_partner', 'tip', 'Show {name} a concrete example or a small test before a big change. Proof convinces them more than vision.'),
  ('curiosity', 'low', 'family', 'who', 'values traditions and things that have stood the test of time'),
  ('curiosity', 'low', 'family', 'who_they', 'They also value traditions and things that have stood the test of time'),
